41	                    ));
42	
43	            List<AddressResponseDto> addresses = user.getAddresses().stream()
44	                    .map(address -> new AddressResponseDto(
45	                            address.getId(),
46	                            // 결정적 암호화된 필드들 복호화
47	                            encryptionUtil.deterministicDecrypt(address.getRecipientName()),
48	                            encryptionUtil.deterministicDecrypt(address.getPhoneNumber()),
