//        try {
//            MessageDigest digest = MessageDigest.getInstance("SHA-256");
//            byte[] hash = digest.digest((secretKey + input).getBytes(StandardCharsets.UTF_8));
//
//            // 32바이트 중 처음 16바이트만 사용 (AES-128)
